import { Component } from '@angular/core';
import { WalletModel } from 'src/app/_models';
import { WalletService } from 'src/app/_services';
import { TransactionService } from 'src/app/_services/transaction/transaction.service';

@Component({
    selector: 'app-transaction-create',
    templateUrl: './transaction-create.component.html',
    styleUrls: ['./transaction-create.component.css']
})
export class TransactionCreateComponent {
    selectWallet(_t49: WalletModel) {
        console.log(_t49);
		this.selectedWallet = _t49;
		this.showDropdown = false;
    }
    addTransaction() {
        throw new Error('Method not implemented.');
    }

    constructor(
        public transactionService: TransactionService,
        public walletService: WalletService
    ) {
        if (walletService.wallets.length == 0) {
            walletService.getWalletsFromServer().subscribe();
        }
    }

    selectedWallet: WalletModel = new WalletModel();

    onWalletChange() {
        if (this.selectedWallet.id != null) {
            this.transactionService.newTransaction.idWallet =
                this.selectedWallet.id;

            console.log(this.transactionService.newTransaction);
        }
    }

    showDropdown = false;
}
<div class="component-header">
    <div>
        <i
            class="bi bi-arrow-left-circle pointer"
            [routerLink]="['/transaction']"
            style="cursor: pointer"
        ></i>
        &nbsp;&nbsp;
        <span>New Transaction</span>
    </div>
</div>

<br />

<div class="childMainPage">
    <div>
        <input
            class="default-input primary"
            type="text"
            [(ngModel)]="this.transactionService.newTransaction.name"
            placeholder="Transaction Name"
        />
    </div>
    <div>
        <input
            class="default-input primary"
            type="text"
            [(ngModel)]="this.transactionService.newTransaction.amount"
            placeholder="Transaction Amount"
        />
    </div>
    <div>
        <input
            class="default-input primary"
            type="text"
            [(ngModel)]="this.transactionService.newTransaction.isIncome"
            placeholder="Wallet Currency Code"
        />
    </div>
    <!-- <div class="default-input composed-select">
        <select
            class="no-style-select"
            [(ngModel)]="selectedWallet"
            (change)="onWalletChange()"
        >
            <option
                *ngFor="let wallet of this.walletService.wallets"
                [ngValue]="wallet"
            >
                {{ wallet.name }}
            </option>
        </select>
    </div> -->

    <!-- <div class="custom-select">
        <select>
            <option
                *ngFor="let wallet of this.walletService.wallets"
                [ngValue]="wallet"
            >
                {{ wallet.name }}
            </option>
        </select>
    </div> -->

	<div class="custom-select default-input">
		<div class="selected-option" (click)="showDropdown = !showDropdown">
			<span *ngIf="!selectedWallet.name">Select Wallet</span>
		  {{ selectedWallet.name }}
		</div>
		<div class="dropdown" *ngIf="showDropdown">
		  <div class="default-dropdown-option" *ngFor="let wallet of walletService.wallets" (click)="selectWallet(wallet)">
			{{ wallet.name }}
		  </div>
		</div>
	  </div>

</div>

<div class="row bottom-button">
    <button class="default-button" (click)="addTransaction()">
        Create Wallet
    </button>
</div>
